//! Metrics P32: auditable-discovery-rate evaluation integrity contracts.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::BTreeSet;
use thiserror::Error;
pub const BOUNDARY:&str=PRECLINICAL_BOUNDARY;
pub const CONTENT_TYPE:&str="application/vnd.aurora.metrics.discovery-rate-integrity-card-1+json";
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct DiscoveryObservation4{pub observation_id:String,pub conclusion_digest:String,pub baseline_digest:String,pub benchmark_world_digest:String,pub evidence_state:String,pub independently_reproduced:bool,pub policy_compliant:bool,pub cost_micros:u64,pub duration_ms:u64,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct DiscoveryRateRequest4{pub schema_version:String,pub request_id:String,pub purpose:String,pub observations:Vec<DiscoveryObservation4>,pub required_observation_order:Vec<String>,pub baseline_digest:String,pub benchmark_world_digest:String,pub metric_version:String,pub replay_identity:String,pub policy_allowed:bool,pub protected_closure:bool,pub signed_manifest:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub adversarial_events:Vec<String>,pub observation_budget:usize,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct DiscoveryRateArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:String,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct DiscoveryRateCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub purpose:String,pub disposition:String,pub observation_order:Vec<String>,pub qualified_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub baseline_order:Vec<String>,pub conclusion_order:Vec<String>,pub evidence_order:Vec<String>,pub replay_identity:String,pub closure_digest:String,pub discovery_numerator:u64,pub discovery_denominator:u64,pub cost_micros:u64,pub duration_ms:u64,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String,pub effect_receipts:Vec<String>,pub artifact:DiscoveryRateArtifact4}
#[derive(Debug,Error)] pub enum DiscoveryRateIntegrityError{#[error("discovery-rate integrity input is invalid: {0}")] Invalid(String),#[error("discovery-rate integrity digest failed: {0}")] Digest(String)}
fn digest(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit())}fn canonical(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])}fn invalid(v:impl Into<String>)->DiscoveryRateIntegrityError{DiscoveryRateIntegrityError::Invalid(v.into())}
pub fn manifest(feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"metrics","consumers":["evaluation engine","research program steward","benchmark operator","research workbench"],"behavior":format!("qualify auditable discovery-rate measurements at {scale} ({mode})"),"value":"measures independently reproducible, policy-compliant research conclusions per unit cost and time against a fixed baseline without inflating automation volume","input_schema":"DiscoveryRateRequest4@1","output_schema":"DiscoveryRateCard7@1","effects":["emit:evaluation-card","retain:negative-rate-evidence","block:unsafe-release"],"permissions":["read:local-evaluation-fixtures"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
fn validate_card(c:&DiscoveryRateCard7)->Result<(),DiscoveryRateIntegrityError>{if c.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||c.feature_id.is_empty()||c.request_id.is_empty()||c.purpose.is_empty()||c.boundary!=BOUNDARY||c.artifact.boundary!=BOUNDARY||!c.raw_data_local||!c.aggregate_only||!digest(&c.replay_identity)||!digest(&c.closure_digest)||c.artifact.content_type!=CONTENT_TYPE||c.artifact.content_hash!=c.closure_digest||c.discovery_numerator>c.discovery_denominator{return Err(invalid("discovery identity, locality, artifact, digest, boundary, or rate is incomplete"));}for v in [&c.observation_order,&c.qualified_order,&c.rejected_order,&c.unknown_order,&c.omitted_order,&c.baseline_order,&c.conclusion_order,&c.evidence_order,&c.effect_receipts]{if !canonical(v){return Err(invalid("discovery vectors are not canonical"));}}let ids=c.observation_order.iter().collect::<BTreeSet<_>>();let states=c.qualified_order.iter().chain(&c.rejected_order).chain(&c.unknown_order).chain(&c.omitted_order).collect::<Vec<_>>();if states.len()!=ids.len()||states.into_iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("observation states do not partition observations"));}Ok(())}
pub fn qualify(q:&DiscoveryRateRequest4,feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Result<DiscoveryRateCard7,DiscoveryRateIntegrityError>{if q.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||q.request_id.trim().is_empty()||q.purpose.trim().is_empty()||q.observations.is_empty()||q.required_observation_order.is_empty()||!canonical(&q.required_observation_order)||!digest(&q.replay_identity)||!digest(&q.baseline_digest)||!digest(&q.benchmark_world_digest)||q.metric_version.trim().is_empty()||q.boundary!=BOUNDARY||!q.raw_data_local||!q.aggregate_only||!canonical(&q.adversarial_events)||q.observation_budget==0{return Err(invalid("discovery identity, ordering, baseline, digest, locality, boundary, or budget is invalid"));}let mut rows=q.observations.clone();rows.sort_by(|a,b|a.observation_id.cmp(&b.observation_id));let mut seen=BTreeSet::new();let mut qualified=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut baselines=BTreeSet::new();let mut conclusions=BTreeSet::new();let mut evidence=BTreeSet::new();let mut cost=0u64;let mut duration=0u64;for o in &rows{if o.observation_id.trim().is_empty()||!seen.insert(o.observation_id.clone())||!digest(&o.conclusion_digest)||!digest(&o.baseline_digest)||!digest(&o.benchmark_world_digest)||o.evidence_state.trim().is_empty()||!o.local||!o.aggregate_only{return Err(invalid("observation identity, digests, evidence, or locality is invalid"));}baselines.insert(format!("{}:{}",o.observation_id,o.baseline_digest));conclusions.insert(format!("{}:{}",o.observation_id,o.conclusion_digest));evidence.insert(o.conclusion_digest.clone());cost=cost.saturating_add(o.cost_micros);duration=duration.saturating_add(o.duration_ms);if o.evidence_state=="unknown"||o.conclusion_digest==q.replay_identity{unknown.insert(o.observation_id.clone());}else if o.baseline_digest!=q.baseline_digest||o.benchmark_world_digest!=q.benchmark_world_digest||!o.independently_reproduced||!o.policy_compliant{rejected.insert(o.observation_id.clone());}else if !q.required_observation_order.contains(&o.observation_id){omitted.insert(o.observation_id.clone());}else{qualified.insert(o.observation_id.clone());}}let missing=q.required_observation_order.iter().filter(|x|!seen.contains(*x)).cloned().collect::<Vec<_>>();let global=!q.policy_allowed||!q.protected_closure||!q.signed_manifest||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty()||rows.len()>q.observation_budget;if global{omitted.extend(seen.iter().cloned());qualified.clear();rejected.clear();unknown.clear();}let disposition=if global{"blocked"}else if !missing.is_empty()||!unknown.is_empty(){"unknown"}else if !rejected.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let body=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":contract_version,"feature_id":feature_id,"request_id":q.request_id,"purpose":q.purpose,"disposition":disposition,"observation_order":seen.iter().cloned().collect::<Vec<_>>()});let closure_digest=ContentHash::of_value(&body).map_err(|e|DiscoveryRateIntegrityError::Digest(e.to_string()))?.to_string();let qualified_order=qualified.into_iter().collect::<Vec<_>>();let rejected_order=rejected.into_iter().collect::<Vec<_>>();let unknown_order=unknown.into_iter().collect::<Vec<_>>();let omitted_order=omitted.into_iter().collect::<Vec<_>>();let artifact=DiscoveryRateArtifact4{artifact_id:format!("metrics-discovery-rate:{}",q.request_id),content_type:CONTENT_TYPE.into(),content_hash:closure_digest.clone(),semantic_loss:omitted_order.clone(),evidence_digests:evidence.into_iter().collect(),boundary:BOUNDARY.into()};let c=DiscoveryRateCard7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:contract_version.into(),feature_id:feature_id.into(),request_id:q.request_id.clone(),purpose:q.purpose.clone(),disposition:disposition.into(),observation_order:body["observation_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),qualified_order:qualified_order.clone(),rejected_order,unknown_order,omitted_order,baseline_order:baselines.into_iter().collect(),conclusion_order:conclusions.into_iter().collect(),evidence_order:artifact.evidence_digests.clone(),replay_identity:q.replay_identity.clone(),closure_digest,discovery_numerator:qualified_order.len() as u64,discovery_denominator:rows.len() as u64,cost_micros:cost,duration_ms:duration,raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into(),effect_receipts:if disposition=="qualified"{vec![format!("approve:discovery-rate:{}",q.request_id)]}else{vec!["block:unsafe-release".into()]},artifact};validate_card(&c)?;let _=(scale,mode);Ok(c)}
